def algorithm(func, dim, lb, ub, budget, rng):
    n = 10 * dim
    mu = 0.5 * (ub - lb) + lb
    sigma = 1.0 * (ub - lb)

    for _ in range(budget):
        candidates = np.clip(mu + rng.normal(size=(n, dim)) * sigma, lb, ub)
        fitnesses = func(candidates)

        best_candidate = candidates[np.argmin(fitnesses)]
        mu = 0.5 * (mu + best_candidate) if budget < 100 else 0.1 * (mu + best_candidate) + 0.9 * mu

    return np.clip(mu, lb, ub)

def algorithm(func, dim, lb, ub, budget, rng):
    best = None
    best_fit = float('inf')

    for _ in range(budget):
        x = (lb + ub) / 2 * np.ones(dim)

        for d in range(dim):
            if rng.random() < 0.5:
                x[d] += (ub - lb) * rng.uniform(-1, 1)
            else:
                x[d] -= (ub - lb) * rng.uniform(0, 1)

            # Clip to bounds
            x[d] = max(lb, min(x[d], ub))

        fit = func(x)

        if fit < best_fit:
            best_fit = fit
            best = x.copy()

    return best

def algorithm(func, dim, lb, ub, budget, rng):
    best_x = None
    best_f = float('inf')

    for _ in range(budget):
        x = np.zeros(dim)
        for i in range(dim):
            x[i] = (ub - lb) * rng.uniform(0, 1) + lb

        f = func(x)

        if f < best_f:
            best_f = f
            best_x = x

        step_size = (ub - lb) / np.sqrt(_ + 1)
        gradient = np.zeros(dim)
        for i in range(dim):
            epsilon = rng.uniform(-1, 1)
            x_epsilon = x.copy()
            x_epsilon[i] += epsilon * step_size
            f_epsilon = func(x_epsilon)

            gradient[i] = (f_epsilon - f) / epsilon

        if best_x is not None:
            for i in range(dim):
                if np.abs(gradient[i]) < 1e-3 and np.abs(best_x[i]) > 0.01 * (ub - lb):
                    step_size *= 2
                    gradient[i] = 0

                    x_epsilon = best_x.copy()
                    x_epsilon[i] += epsilon * step_size
                    f_epsilon = func(x_epsilon)

                    if f_epsilon < best_f:
                        best_f = f_epsilon
                        best_x = x_epsilon

    return np.clip(best_x, lb, ub)
